<script setup lang="ts">
import { ArrowDown, Braces, Flag, GitBranch, Minus, Plus, Save, Play, Upload } from '@lucide/vue'
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { studioApi, errorText } from '@/api/client'
import type { FlowSummary, ValidationIssue } from '@/api/types'
import { createEditorState } from './state'
import type { FlowNode, NodeType, Stage } from './sample'
import acceptanceCases from './fixtures/order-admission.cases.json'
import StageCard from './components/StageCard.vue'
import NodePalette from './components/NodePalette.vue'
import InspectorPanel from './components/InspectorPanel.vue'
import NodeConfigDialog from './components/NodeConfigDialog.vue'
import ExecutionPanel from './components/ExecutionPanel.vue'
import { locateIssue } from './issueLocation'
const route = useRoute(), router = useRouter()
const editor = createEditorState()
const selectedStageId = ref(''), selectedNodeId = ref(''), dialogOpen = ref(false), zoom = ref(100), activeTab = ref<'canvas'|'facts'|'versions'>('canvas')
const versions = ref<FlowSummary[]>([]), versionError = ref('')
const leaveOpen = ref(false), pendingRoute = ref(''), allowNavigation = ref(false)
const publishOpen = ref(false), publishNote = ref(''), inspectorInvalid = ref(false), dialogInvalid = ref(false)
const invalidEditorInput = computed(() => inspectorInvalid.value || dialogInvalid.value)
const focusItemId = ref<string | null>(null), focusField = ref<string | null>(null)
const factCases = acceptanceCases.filter(item => ['OA-01','OA-02','OA-07','OA-08','OA-09'].includes(item.id))
const stages = computed(() => [...(editor.document.value?.stages ?? [])].sort((a,b) => a.order - b.order))
const selectedStage = computed(() => stages.value.find(s => s.stageId === selectedStageId.value) ?? stages.value[0])
const selectedNode = computed(() => selectedNodeId.value ? stages.value.flatMap(s => s.nodes).find(n => n.nodeId === selectedNodeId.value) : undefined)
const nodeCount = computed(() => stages.value.reduce((sum,s) => sum+s.nodes.length, 0))
const visibleIssues = computed(() => editor.issues.value)
const currentFlowId = computed(() => String(route.params.flowId ?? ''))
const currentVersion = computed(() => String(route.params.version ?? ''))
function selectStage(id: string) { selectedStageId.value = id; selectedNodeId.value = ''; inspectorInvalid.value = false }
function selectNode(id: string, stageId: string) { selectedStageId.value = stageId; selectedNodeId.value = id; inspectorInvalid.value = false }
async function load() {
  const flowId = currentFlowId.value, version = currentVersion.value
  publishOpen.value = false; publishNote.value = ''; dialogOpen.value = false; inspectorInvalid.value = false; dialogInvalid.value = false
  await editor.load(flowId, version)
  if (flowId !== currentFlowId.value || version !== currentVersion.value) return
  selectedStageId.value = editor.document.value?.stages[0]?.stageId ?? ''
  selectedNodeId.value = ''
  await loadVersions()
}
async function loadVersions() { try { versions.value = (await studioApi.listVersions(currentFlowId.value)).items; versionError.value = '' } catch (e) { versionError.value = errorText(e) } }
watch([currentFlowId, currentVersion], load, { immediate: true })
function beforeUnload(event: BeforeUnloadEvent) { if (editor.dirty.value || invalidEditorInput.value) event.preventDefault() }
onMounted(() => window.addEventListener('beforeunload', beforeUnload))
onUnmounted(() => window.removeEventListener('beforeunload', beforeUnload))
function guardLeave(path: string) { if ((!editor.dirty.value && !invalidEditorInput.value) || allowNavigation.value) return true; pendingRoute.value = path; leaveOpen.value = true; return false }
onBeforeRouteLeave(to => guardLeave(to.fullPath))
onBeforeRouteUpdate(to => guardLeave(to.fullPath))
async function discardAndLeave() { leaveOpen.value = false; allowNavigation.value = true; await router.push(pendingRoute.value); allowNavigation.value = false }
function editStage(patch: Partial<Stage>) { const id = selectedStage.value?.stageId; editor.mutate(doc => Object.assign(doc.stages.find(s => s.stageId === id)!, patch)) }
function editNode(patch: Partial<FlowNode>) { const id = selectedNodeId.value; editor.mutate(doc => Object.assign(doc.stages.flatMap(s => s.nodes).find(n => n.nodeId === id)!, patch)) }
function editConfig(patch: Record<string, unknown>) { const id = selectedNodeId.value; editor.mutate(doc => Object.assign(doc.stages.flatMap(s => s.nodes).find(n => n.nodeId === id)!.config, patch)) }
function reorder<T extends { order: number }>(items: T[], index: number, offset: number) { const target = index + offset; if (target < 0 || target >= items.length) return; [items[index], items[target]] = [items[target]!, items[index]!]; items.forEach((item,i) => item.order = i+1) }
function moveStage(offset: number) { const id = selectedStage.value?.stageId; editor.mutate(doc => { const items = doc.stages.sort((a,b) => a.order-b.order); reorder(items, items.findIndex(s => s.stageId === id), offset) }) }
function removeStage() { const id = selectedStage.value?.stageId; if (!window.confirm('删除此阶段及全部节点？')) return; editor.mutate(doc => { doc.stages = doc.stages.filter(s => s.stageId !== id); doc.stages.forEach((s,i) => s.order = i+1) }); selectedStageId.value = stages.value[0]?.stageId ?? ''; selectedNodeId.value = '' }
function addStage() { const id = `stage_${crypto.randomUUID().slice(0,8)}`; editor.mutate(doc => doc.stages.push({ stageId:id, stageName:'新阶段', order:doc.stages.length+1, executionMode:'SERIAL', when:null, timeoutMillis:1000, nodes:[] })); selectStage(id); activeTab.value = 'canvas' }
function moveNode(offset: number) { const stageId = selectedStageId.value, id = selectedNodeId.value; editor.mutate(doc => { const items = doc.stages.find(s => s.stageId === stageId)!.nodes.sort((a,b) => a.order-b.order); reorder(items, items.findIndex(n => n.nodeId === id), offset) }) }
function removeNode() { if (!window.confirm('删除此节点？')) return; const stageId = selectedStageId.value, id = selectedNodeId.value; editor.mutate(doc => { const stage = doc.stages.find(s => s.stageId === stageId)!; stage.nodes = stage.nodes.filter(n => n.nodeId !== id); stage.nodes.forEach((n,i) => n.order = i+1) }); selectedNodeId.value = '' }
function addNode(type: NodeType) { const stageId = selectedStage.value?.stageId; if (!stageId) return; const id = `node_${crypto.randomUUID().slice(0,8)}`; editor.mutate(doc => { const stage = doc.stages.find(s => s.stageId === stageId)!; const base = { nodeId:id, nodeName:({ 'openrule.operator':'新条件判断','openrule.rule-set':'新规则集','openrule.scorecard':'新评分卡','openrule.decision-table':'新决策表','openrule.terminal':'新最终决策' } as Record<NodeType,string>)[type], order:stage.nodes.length+1, type, configVersion:1, timeoutMillis:Math.min(stage.timeoutMillis,1000) }; const outputKey = `output${stage.nodes.length+1}`; const config = type === 'openrule.operator' ? { condition:null, outputKey, reasonCode:null } : type === 'openrule.rule-set' ? { outputKey, matchPolicy:'FIRST_MATCH' as const, rules:[] } : type === 'openrule.scorecard' ? { outputKey, characteristics:[] } : type === 'openrule.decision-table' ? { outputKey, hitPolicy:'FIRST' as const, rules:[] } : { decisionCode:null, reasonCodes:[], scoreRef:null }; stage.nodes.push({ ...base, ...(type === 'openrule.terminal' ? {} : { failPolicy:'ABORT' as const }), config } as FlowNode) }); selectNode(id,stageId); activeTab.value = 'canvas'; if (!['openrule.operator','openrule.terminal'].includes(type)) dialogOpen.value = true }
async function jumpIssue(issue: ValidationIssue) { if (!editor.document.value) return; const location = locateIssue(editor.document.value, issue); if (location.stageId) selectStage(location.stageId); if (location.nodeId && location.stageId) selectNode(location.nodeId, location.stageId); activeTab.value='canvas'; const advanced = location.nodeId && editor.document.value.stages.flatMap(stage => stage.nodes).find(node => node.nodeId === location.nodeId && ['openrule.rule-set','openrule.scorecard','openrule.decision-table'].includes(node.type)); if (advanced) { focusItemId.value = location.itemId; focusField.value = location.field; dialogOpen.value = true; await nextTick(); if (!location.itemId) document.querySelector('.config-dialog [data-field="outputKey"]')?.scrollIntoView({ block:'center' }); return } dialogOpen.value = false; await nextTick(); const target = location.field ? document.querySelector(`.inspector [data-field="${location.field}"]`) as HTMLElement | null : null; target?.focus(); (target ?? document.querySelector('.inspector'))?.scrollIntoView({ block:'nearest' }) }
function openPublish() { editor.message.value = ''; publishOpen.value = true }
async function confirmPublish() { if (invalidEditorInput.value) return; const okay = await editor.publish(publishNote.value); if (okay) { publishOpen.value = false; await loadVersions() } }
function applyCase(id: string) { const selected = factCases.find(item => item.id === id); if (selected) editor.factsText.value = JSON.stringify(selected.facts, null, 2) }
async function createNextDraft() { const resource = editor.resource.value; if (!resource || resource.status !== 'PUBLISHED') return; try { const next = await studioApi.createDraft(resource.flowId, resource.version); await router.push(`/flows/${next.flowId}/versions/${next.version}`) } catch(e) { editor.message.value = errorText(e) } }
function openVersions() { activeTab.value = 'versions'; loadVersions() }
</script>
<template>
  <div class="editor-page" :class="{ 'canvas-active': activeTab === 'canvas' }" v-if="editor.document.value && editor.resource.value">
    <div class="editor-title"><div class="editor-name"><span class="flow-symbol"><GitBranch :size="23" /></span><div><div class="title-line"><h1>{{ editor.document.value.flowName }}</h1><Badge variant="secondary">v{{ editor.resource.value.version }}</Badge><span class="sample-badge">{{ editor.resource.value.status }} · r{{ editor.resource.value.revision }}</span><span v-if="editor.dirty.value" class="unsaved-badge">未保存</span></div><p><code>{{ editor.resource.value.flowId }}</code><span>·</span>调用方提供完整 facts · 服务端执行</p></div></div>
      <div class="editor-actions"><Button v-if="editor.readOnly.value" variant="outline" @click="createNextDraft">从此版本创建草稿</Button><template v-else><Button variant="outline" :disabled="editor.saving.value || editor.publishing.value || invalidEditorInput" @click="editor.save()"><Save :size="15" />{{ editor.saving.value ? '保存中…' : '保存草稿' }}</Button><Button variant="outline" :disabled="editor.validating.value || editor.publishing.value || invalidEditorInput" @click="editor.validate()">校验</Button><Button :disabled="editor.simulating.value || editor.saving.value || editor.publishing.value || invalidEditorInput" @click="editor.saveAndSimulate()"><Play :size="15" />{{ editor.simulating.value ? '试运行中…' : '保存并试运行' }}</Button></template><Button v-if="!editor.readOnly.value" variant="outline" :disabled="editor.publishing.value || editor.saving.value" @click="openPublish"><Upload :size="15" />发布版本</Button></div></div>
    <div class="editor-tabbar"><div class="editor-tabs"><button class="editor-tab" :class="{active:activeTab==='canvas'}" @click="activeTab='canvas'"><GitBranch :size="15" />可视化编排</button><button class="editor-tab" :class="{active:activeTab==='facts'}" @click="activeTab='facts'"><Braces :size="15" />输入事实</button><button class="editor-tab" :class="{active:activeTab==='versions'}" @click="openVersions">版本记录</button></div><span class="tab-context">{{ editor.readOnly.value ? '已发布 · 只读' : '草稿 · CAS revision' }}</span></div>
    <div v-if="editor.message.value" class="notice" :class="{error: editor.message.value.includes('OR-') || editor.message.value.includes('失败') || editor.message.value.includes('无法')}">{{ editor.message.value }}</div>
    <div v-if="editor.issues.value.length" class="issue-strip"><strong>校验问题 {{ visibleIssues.length }}</strong><button v-for="(issue,index) in visibleIssues" :key="index" type="button" @click="jumpIssue(issue)">{{ issue.stageId ?? 'Flow' }}{{ issue.nodeId ? ` / ${issue.nodeId}` : '' }} · {{ issue.message }} <small>{{ issue.pointer }}</small></button></div>
    <div v-if="activeTab==='canvas'" class="editor-content"><NodePalette :stage-count="stages.length" :node-count="nodeCount" :read-only="editor.readOnly.value || editor.publishing.value" @add-node="addNode" /><section class="flow-canvas" aria-label="决策流程画布"><div class="canvas-toolbar"><span class="canvas-tag">LINEAR FLOW</span><span>按阶段顺序展示</span><template v-if="!editor.readOnly.value"><button class="inline-action" @click="addStage">+ 阶段</button><button class="inline-action compact-node-add" @click="addNode('openrule.operator')">+ 条件</button><button class="inline-action compact-node-add" @click="addNode('openrule.terminal')">+ 终点</button></template><div class="zoom-control"><button type="button" aria-label="缩小画布" @click="zoom=Math.max(80,zoom-10)"><Minus :size="13" /></button><span>{{ zoom }}%</span><button type="button" aria-label="放大画布" @click="zoom=Math.min(120,zoom+10)"><Plus :size="13" /></button></div></div><div class="canvas-scroll"><div class="flow-chain" :style="{zoom:`${zoom}%`}"><div class="flow-start"><span class="start-dot" />开始 <span class="start-badge">调用方 facts</span></div><div class="chain-line"><ArrowDown :size="12" /></div><StageCard v-for="(stage,index) in stages" :key="stage.stageId" :stage="stage" :selected-stage-id="selectedStageId" :selected-node-id="selectedNodeId" :last="index===stages.length-1" @select-stage="selectStage" @select-node="selectNode" /><div class="chain-line" /><div class="canvas-end"><Flag :size="13" />最终决策由 Terminal 输出</div></div></div><div class="canvas-status"><span><i class="status-dot" />{{ editor.resource.value.status }} · revision {{ editor.resource.value.revision }}</span><span>{{ stages.length }} stages <span class="dot-separator">/</span>{{ nodeCount }} nodes</span></div></section><InspectorPanel :key="`${selectedStageId}:${selectedNodeId}`" :node="selectedNode" :stage="selectedStage" :read-only="editor.readOnly.value || editor.publishing.value" @edit-stage="editStage" @edit-node="editNode" @edit-config="editConfig" @move-stage="moveStage" @remove-stage="removeStage" @move-node="moveNode" @remove-node="removeNode" @open-config="dialogOpen=true" @invalid="inspectorInvalid=$event" /></div>
    <section v-if="activeTab==='facts'" class="workspace-panel"><h2>试运行输入</h2><p>完整 facts JSON；数字按原始字面量发送，null 与缺失字段保持不同。</p><div class="fact-presets"><button v-for="sample in factCases" :key="sample.id" class="inline-action" @click="applyCase(sample.id)">{{ sample.id }} · {{ sample.expected.decisionCode ?? "技术失败" }}</button></div><textarea v-model="editor.factsText.value" spellcheck="false" aria-label="facts JSON" /><div class="panel-actions"><Button :disabled="editor.readOnly.value || editor.simulating.value || editor.publishing.value || invalidEditorInput" @click="editor.saveAndSimulate()">保存并试运行</Button></div><ExecutionPanel v-if="editor.result.value" :result="editor.result.value" :document="editor.document.value" :stale="editor.staleResult.value" /></section>
    <section v-if="activeTab==='versions'" class="workspace-panel"><h2>版本记录</h2><p>精确读取服务端版本。已发布版本始终只读。</p><div v-if="versionError" class="notice error">{{ versionError }}</div><div v-for="version in versions" :key="version.version" class="version-row"><RouterLink :to="`/flows/${version.flowId}/versions/${version.version}`">v{{ version.version }}</RouterLink><span>{{ version.status }}</span><span>revision {{ version.revision }}</span><code>{{ version.definitionChecksum ?? '未发布' }}</code></div></section>
    <NodeConfigDialog :node="selectedNode" :open="dialogOpen" :read-only="editor.readOnly.value || editor.publishing.value" :focus-item-id="focusItemId" :focus-field="focusField" @update:open="dialogOpen=$event" @edit-config="editConfig" @invalid="dialogInvalid=$event" />
    <div v-if="publishOpen" class="leave-overlay" role="dialog" aria-modal="true" aria-label="发布版本"><div class="leave-card publish-card"><h2>发布精确版本 v{{ editor.resource.value.version }}</h2><p>发布后此版本只读。服务端将校验当前 revision；不激活 Scene。</p><p v-if="editor.dirty.value" class="result-failure">当前有未保存修改。请先关闭弹窗并保存，再确认发布。</p><p v-if="invalidEditorInput" class="result-failure">请先修正配置编辑器中的无效输入。</p><p v-if="editor.message.value" class="result-failure" role="alert">{{ editor.message.value }}</p><label class="field-label">发布说明 · 必填<textarea v-model="publishNote" :disabled="editor.publishing.value" placeholder="描述本次规则变更" /></label><div><Button variant="outline" :disabled="editor.publishing.value" @click="publishOpen=false">取消</Button><Button :disabled="!publishNote.trim() || editor.dirty.value || editor.publishing.value || invalidEditorInput" @click="confirmPublish">{{ editor.publishing.value ? '发布中…' : '确认发布' }}</Button></div></div></div>
    <div v-if="leaveOpen" class="leave-overlay" role="dialog" aria-modal="true" aria-label="未保存修改"><div class="leave-card"><h2>草稿有未保存修改</h2><p>离开后，本次修改不会写入服务端。</p><div><Button variant="outline" @click="leaveOpen=false">继续编辑</Button><Button @click="discardAndLeave">放弃修改并离开</Button></div></div></div>
  </div><div v-else class="workspace-panel">{{ editor.loading.value ? '正在读取精确版本…' : editor.message.value || '未找到版本' }} <RouterLink to="/">返回列表</RouterLink></div>
</template>
